\begin{tikzpicture}
\begin{axis}[
    width=0.82\textwidth,
    height=0.50\textwidth,
    xmin=-2.4, xmax=2.4,
    ymin=-5, ymax=4,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={},
    xtick={-2,-1.414,0,1.414,2},
    xticklabels={\(-2\),\(-\sqrt2\),\(0\),\(\sqrt2\),\(2\)},
    ytick={-4,-2,0,2},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[thick, domain=-2.2:2.2, samples=250] {x^4-4*x^2};

\addplot[only marks, mark=*] coordinates {(-1.414,-4) (0,0) (1.414,-4)};
\addplot[only marks, mark=o, mark size=2.5pt, thick] coordinates {(-0.816,-2.222) (0.816,-2.222)};

\node[anchor=north] at (axis cs:-1.414,-4) {local min};
\node[fill=white, inner sep=1pt, anchor=south west] at (axis cs:0.12,0.18) {local max};
\node[anchor=north] at (axis cs:1.414,-4) {local min};

\node[anchor=south east] at (axis cs:-0.816,-2.222) {inflection};
\node[anchor=south west] at (axis cs:0.816,-2.222) {inflection};
\end{axis}
\end{tikzpicture}

p.me:
\begin{array}{ll}
\text{1.} \amp \text{Find the domain.}\\
\text{2.} \amp \text{Look for symmetry and intercepts.}\\
\text{3.} \amp \text{Find asymptotes and end behavior with limits.}\\
\text{4.} \amp \text{Compute } f'(x) \text{ and make a sign chart.}\\
\text{5.} \amp \text{Use } f' \text{ to find increasing/decreasing intervals and local extrema.}\\
\text{6.} \amp \text{Compute } f''(x) \text{ and make a sign chart.}\\
\text{7.} \amp \text{Use } f'' \text{ to find concavity and inflection points.}\\
\text{8.} \amp \text{Plot reliable points and sketch a graph that obeys all the evidence.}
\end{array}

\begin{array}{c|cccc}
\text{interval} \amp (-\infty,-1) \amp (-1,0) \amp (0,1) \amp (1,\infty)\\
\hline
f''(x) \amp - \amp + \amp - \amp +\\
f \amp \text{concave down} \amp \text{concave up} \amp \text{concave down} \amp \text{concave up}
\end{array}

image.latex-image:
\begin{tikzpicture}
\begin{axis}[
    width=0.86\textwidth,
    height=0.56\textwidth,
    xmin=-4, xmax=4,
    ymin=-8, ymax=8,
    axis lines=middle,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={-3,-1,0,1,3},
    ytick={-6,-3,0,3,6},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    clip=true,
]
% function branches
\addplot[thick, domain=-4:-1.04, samples=200] {x^3/(x^2-1)};
\addplot[thick, domain=-0.96:0.96, samples=200] {x^3/(x^2-1)};
\addplot[thick, domain=1.04:4, samples=200] {x^3/(x^2-1)};

% asymptotes
\addplot[dashed, domain=-4:4, samples=2] {x};
\draw[dashed] (axis cs:-1,-8) -- (axis cs:-1,8);
\draw[dashed] (axis cs:1,-8) -- (axis cs:1,8);

% important points
\addplot[only marks, mark=*] coordinates {(-1.732,-2.598) (0,0) (1.732,2.598)};
\node[fill=white, inner sep=1pt, anchor=west] at (axis cs:-1.732,-2.598) {local max};
\node[fill=white, inner sep=1pt, anchor=west] at (axis cs:1.732,2.598) {local min};
\node[fill=white, inner sep=1pt, anchor=west] at (axis cs:0,0) {inflection};
\node[fill=white, inner sep=1pt, anchor=north] at (axis cs:2.55,2.35) {\(y=x\)};
\node[anchor=west] at (axis cs:1.12,6.5) {\(x=1\)};
\node[anchor=east] at (axis cs:-1.12,6.5) {\(x=-1\)};
\end{axis}
\end{tikzpicture}
